const form=document.querySelector('#tradeinForm');if(form){const faq=document.createElement('section');faq.className='faq';faq.innerHTML='<p>ANTES DE EMPEZAR</p><h2>Claro y sin vueltas.</h2><details open><summary>¿Qué equipos toman?</summary><span>Evaluamos iPhone y otros smartphones según modelo, estado, batería y funcionamiento.</span></details><details><summary>¿Cuánto demora?</summary><span>Respondemos en hasta 15 minutos dentro del horario de atención.</span></details><details><summary>¿Cómo envío las fotos?</summary><span>Adjuntalas en el formulario y te contactamos por WhatsApp o email.</span></details>';form.parentNode.insertBefore(faq,form);form.addEventListener('submit',(event)=>{event.preventDefault();const files=[...form.querySelector('input[type=file]').files].map(file=>file.name).join(', ');document.querySelector('#tradeinStatus').innerHTML=`Solicitud preparada con ${files?`las fotos: ${files}. `:'tus datos. '}La conexión al canal de atención se activará al configurar el WhatsApp o email oficial.`;});}
